INSERT INTO "public"."settings" ("key", "value", "updated_at") VALUES
	('seo', '{"sitemap": "", "keywords": "Leggings, Biker Shorts, Cycling Shorts, Yoga Pants, High Waisted Leggings, High Waisted Leggings, Gym Shorts, Gym Leggings, Booty Shorts, Booty Leggings, Plus Size Leggings, Plus Size shorts Workout Shorts, Workout Leggings, legging Packs, black leggings, scrunch leggings, scrunch shorts, Butt Leggings, Leggings with Pockets", "og_image": "https://vptbrllldcvgykpfljjd.supabase.co/storage/v1/object/public/admin-uploads/settings/og_image_1782772439113.jpg", "faq_schema": [{"items": [{"a": "The best leggings and biker shorts should feel snug without being restrictive. A good fit stays in place during movement, supports your body comfortably, and works just as well for workouts as it does for everyday wear.", "q": "Finding the Right Fit in Leggings and Biker Shorts"}, {"a": "Fabric is what separates average leggings from great ones. Look for breathable, soft materials with four-way stretch and moisture-wicking performance. These features help workout leggings stay comfortable, dry, and flexible through any activity.", "q": "Choosing the Best Fabric for Workout Leggings"}, {"a": "High-waisted leggings and biker shorts are loved for a reason. They offer extra core support, stay securely in place, and create a flattering shape. Perfect for yoga, running, gym sessions, or daily wear, they combine style with function.", "q": "Why High-Waisted Leggings and Biker Shorts Are So Popular"}], "title": ""}, {"items": [{"a": "Compression leggings provide a more supportive, held-in feel that’s ideal for high-intensity workouts and recovery. Regular leggings focus more on comfort and versatility for everyday wear. Choosing between them depends on your lifestyle and activity level.", "q": "Compression Leggings vs Regular Leggings"}, {"a": "Great biker shorts go beyond basic style. Features like squat-proof fabric, side pockets, seamless design, and sweat-wicking technology add comfort and practicality, making them ideal for both workouts and casual outfits.", "q": "Must-Have Features in Biker Shorts for Women"}, {"a": "Investing in quality leggings and biker shorts pays off in the long run. Better fabrics maintain their shape, last longer, and feel more comfortable throughout the day, meaning fewer replacements and better performance over time.", "q": "Why Quality Activewear Leggings Are Worth It"}], "title": ""}], "meta_title": "Women''s Leggings & Biker Shorts | Best Activewear for Women", "robots_txt": "", "meta_description": "Discover the best women''s leggings and biker shorts with real reviews, buying guides, and top activewear picks. Compare styles, brands, and features to find the perfect pair for every workout and everyday comfort."}', '2026-06-26 18:43:37.340823+00'),
	('sidebar', '{"sidebar_ad_script": "", "recent_articles_count": 3, "recent_articles_title": "Recent Articles"}', '2026-06-26 18:43:37.340823+00'),
	('menu_footer', '{"columns": [{"items": [{"url": "/catalogue/biker-shorts", "label": "Biker Shorts"}, {"url": "/catalogue/fleece-leggings", "label": "Fleece Leggings"}, {"url": "/catalogue/high-waisted-leggings", "label": "High Waisted Leggings"}, {"url": "/catalogue/scrunch-shorts", "label": "Scrunch Shorts"}, {"url": "/catalogue/plus-size-leggings", "label": "Plus Size Leggings"}, {"url": "/catalogue/flare-leggings", "label": "Flare Leggings"}], "title": "CATEGORIES"}, {"items": [{"url": "/catalogue/leggings-with-pockets", "label": "With Pockets"}, {"url": "/catalogue/fleece-leggings", "label": "Fleece"}, {"url": "/catalogue/workout-leggings", "label": "For Workout"}, {"url": "/catalogue/yoga-pants", "label": "For Yoga"}, {"url": "/catalogue/gym-shorts", "label": "For Gym"}, {"url": "/catalogue/booty-shorts", "label": "Booty Shorts"}], "title": "SHOP BY STYLES "}, {"items": [{"url": "/contact", "label": "Contact"}, {"url": "/about", "label": "About Us"}, {"url": "/blog", "label": "Blog "}, {"url": "/terms", "label": "Terms of Use"}, {"url": "/disclaimer", "label": "Disclaimer"}, {"url": "/privacy", "label": "Privacy Policy"}], "title": "INFORMATION"}], "logo_text": "leggings", "description": "Discover the best women''s leggings and biker shorts with real reviews, buying guides, and top activewear picks. Compare styles, brands, and features to find the perfect pair for every workout and everyday comfort.", "social_links": [{"url": "", "icon": "instagram", "platform": "Instagram"}, {"url": "", "icon": "twitter", "platform": "Twitter"}, {"url": "", "icon": "youtube", "platform": "Youtube"}]}', '2026-06-26 18:43:37.340823+00'),
